import { NextRequest, NextResponse } from "next/server";
import { buildClientConfigs, hubScaffold } from "@/lib/clients";
import { listServers } from "@/lib/servers";

/**
 * GET /api/clients?serverId=<id> | ?url=<url>&name=<name>&authEnvVar=<NAME>
 * Returns the 8 popular-AI configs for that server, generated by
 * lib/clients.ts (valid JSON, env-var-name-only auth). With no params,
 * returns configs for this hub itself.
 */
export async function GET(req: NextRequest) {
  const q = req.nextUrl.searchParams;
  const serverId = q.get("serverId");
  const url = q.get("url");
  const name = q.get("name");
  if (serverId) {
    const servers = await listServers();
    const s = servers.find((x) => x.id === serverId);
    if (!s) return NextResponse.json({ error: "Server not found." }, { status: 404 });
    return NextResponse.json({ server: { name: s.name, url: s.url }, clients: buildClientConfigs({ name: s.name, url: s.url, transport: s.transport, authEnvVar: s.authEnvVar || undefined }) });
  }
  if (url && name) {
    return NextResponse.json({ server: { name, url }, clients: buildClientConfigs({ name, url, authEnvVar: q.get("authEnvVar") || undefined }) });
  }
  const origin = req.headers.get("host") ? `${req.nextUrl.protocol}//${req.headers.get("host")}` : "http://localhost:3100";
  const hub = hubScaffold(origin);
  return NextResponse.json({ server: hub, clients: buildClientConfigs(hub) });
}
